COMPONENT = {
    "name": "sorted_stack_greedy_relocation",
    "slot": "construction_machine",
    "compatible_skeletons": ["CONSTRUCT"],
    "requires": [],
    "params": {
        "prefer_most_sorted_source": {"type": "bool", "default": True},
        "prefer_highest_destination": {"type": "bool", "default": True},
    },
}

from core.rules import RuleMachine


class SortedStackRelocationRule:
    """Permite solo movimientos desde una pila no totalmente bien puesta hacia una pila ya ordenada,
    y únicamente si el contenedor queda bien puesto en el destino."""

    name = "sorted_stack_relocation"

    def __init__(self, problem, prefer_most_sorted_source=True, prefer_highest_destination=True):
        self.problem = problem
        self.prefer_most_sorted_source = prefer_most_sorted_source
        self.prefer_highest_destination = prefer_highest_destination

    def allowed(self, partial, memory, candidates):
        if not candidates:
            return []

        h = partial.h
        g = partial.g
        e = partial.e
        is_sorted_stack = partial.is_sorted_stack
        sorted_n = getattr(partial, "sorted_n", None)

        def source_key(a):
            # Preferir pilas menos "terminadas" (más bloqueadas).
            if sorted_n is not None and 0 <= a.so < len(sorted_n):
                return (sorted_n[a.so], h(a.so))
            return (0, h(a.so))

        def dest_key(a):
            # Preferir destinos más altos y más ordenados.
            return (h(a.sd), -g(a.sd))

        allowed = []
        for a in candidates:
            if a.so == a.sd:
                continue
            if h(a.so) <= 0 or e(a.sd) <= 0:
                continue

            top = g(a.so)
            dest_top = g(a.sd)

            # Destino ya ordenado y el contenedor queda bien puesto encima.
            if not is_sorted_stack(a.sd):
                continue
            if top > dest_top:
                continue

            # Regla angosta: no mover desde una pila totalmente bien puesta
            # salvo que la propia pila fuente sea la única que siga bloqueando.
            if sorted_n is not None and h(a.so) == sorted_n[a.so]:
                continue

            allowed.append(a)

        if not allowed:
            return []

        if self.prefer_most_sorted_source and self.prefer_highest_destination:
            allowed.sort(key=lambda a: (source_key(a), dest_key(a)))
        elif self.prefer_most_sorted_source:
            allowed.sort(key=lambda a: source_key(a))
        elif self.prefer_highest_destination:
            allowed.sort(key=lambda a: dest_key(a))

        return allowed


def build_component(problem, **params):
    return RuleMachine(
        problem,
        [
            SortedStackRelocationRule(
                problem,
                prefer_most_sorted_source=bool(
                    params.get("prefer_most_sorted_source", COMPONENT["params"]["prefer_most_sorted_source"]["default"])
                ),
                prefer_highest_destination=bool(
                    params.get("prefer_highest_destination", COMPONENT["params"]["prefer_highest_destination"]["default"])
                ),
            )
        ],
    )
